VALUES ('0aab7757-0715-4dd4-beba-06e1ad2c9a54', 'pricing', 'businesses', 'Businesses', 'PUBLISHED', 1, '{"id":"businesses","label":"Businesses","plans":[{"name":"GST Essentials","price":1499,"unit":"/ month","description":"Monthly GST compliance for small traders and service providers.","quota":"12 × GSTR-1 + 12 × GSTR-3B","features":["GSTR-1 and GSTR-3B filing","GSTR-2B reconciliation","Up to 100 invoices per month","Due-date reminders"]},{"name":"Compliance Suite","price":4999,"unit":"/ month","description":"GST, TDS and bookkeeping in one plan.","quota":"GST + TDS + monthly books","popular":true,"features":["Everything in GST Essentials","Monthly bookkeeping (up to 300 transactions)","Quarterly TDS returns","Monthly P&L and balance sheet","Dedicated accountant"]},{"name":"Growth","price":9999,"unit":"/ month","description":"For companies with payroll, audits and ROC obligations.","quota":"Full finance back office","features":["Everything in Compliance Suite","Payroll for up to 25 employees","ROC annual filings","Audit coordination","Quarterly CFO review call"]}]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
