VALUES ('5504b049-27fc-4757-803c-7c297772156b', 'testimonials', 'rohit-malhotra', 'Rohit Malhotra', 'PUBLISHED', 1, '{"name":"Rohit Malhotra","role":"Founder, D2C skincare brand","rating":5,"quote":"We moved our GST and books to them after a messy year with a freelancer. Reconciliation is on time every month and we finally trust our input credit numbers.","initials":"RM"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
