-- faqs (10)
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('38889531-7f37-42a0-b241-5e14fa29282a', 'faqs', 'which-itr-should-i-file', 'Which ITR should I file?', 'PUBLISHED', 0, '{"question":"Which ITR should I file?","answer":"It depends on your sources of income. ITR-1 covers salary, one house property and other income up to ₹50 lakh; ITR-2 adds capital gains and multiple properties; ITR-3 and ITR-4 apply to business or professional income. We confirm the right form after a short review."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('173c79b5-84af-45ab-8bc6-a4fc855f3264', 'faqs', 'what-documents-are-required-for-itr-filing', 'What documents are required for ITR filing?', 'PUBLISHED', 1, '{"question":"What documents are required for ITR filing?","answer":"Typically PAN, Aadhaar, Form 16, Form 26AS/AIS, bank interest certificates, capital gains statements and proof of investments. Your professional shares a precise checklist based on your profile."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('f0b3a7e5-08a6-41bd-b301-79b03882e311', 'faqs', 'how-does-gst-registration-work', 'How does GST registration work?', 'PUBLISHED', 2, '{"question":"How does GST registration work?","answer":"We collect your PAN, business proof and address documents, file the application on the GST portal, respond to any clarification and share your GSTIN — usually within 7 working days."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('d87b0fa2-d16d-471e-8396-4e8f9267b5d9', 'faqs', 'how-often-should-gst-returns-be-filed', 'How often should GST returns be filed?', 'PUBLISHED', 3, '{"question":"How often should GST returns be filed?","answer":"Regular taxpayers file GSTR-1 and GSTR-3B monthly; QRMP taxpayers file quarterly with monthly payments; composition dealers file quarterly CMP-08 and annual GSTR-4. An annual GSTR-9 applies above the turnover threshold."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('a652a4f9-bc32-4c69-aa3d-56070b57f198', 'faqs', 'can-you-handle-accounting-for-my-business', 'Can you handle accounting for my business?', 'PUBLISHED', 4, '{"question":"Can you handle accounting for my business?","answer":"Yes. We offer monthly bookkeeping, payroll, reconciliations and financial statements with a dedicated accountant, in Tally, Zoho Books or QuickBooks."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('bfd10578-84ac-4268-92a7-9795a39664ea', 'faqs', 'how-long-does-company-registration-take', 'How long does company registration take?', 'PUBLISHED', 5, '{"question":"How long does company registration take?","answer":"A Private Limited company or LLP is typically incorporated within 7–12 working days once documents are ready, subject to MCA processing and name availability."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('8fe5121b-f0c0-4c24-93d4-36ebd4422d19', 'faqs', 'do-you-provide-tax-planning', 'Do you provide tax planning?', 'PUBLISHED', 6, '{"question":"Do you provide tax planning?","answer":"Yes. Tax planning engagements cover regime selection, salary structuring, investments, capital gains planning and advance tax, with a mid-year review."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('4048fc62-2c00-445e-b906-a70043c54b92', 'faqs', 'can-i-speak-directly-with-an-expert', 'Can I speak directly with an expert?', 'PUBLISHED', 7, '{"question":"Can I speak directly with an expert?","answer":"Absolutely. Every engagement is handled by a named professional you can reach by phone, WhatsApp or through the client portal."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('f4e6d04c-c8af-4998-b69c-dc95f6258909', 'faqs', 'how-are-my-documents-protected', 'How are my documents protected?', 'PUBLISHED', 8, '{"question":"How are my documents protected?","answer":"Documents are stored encrypted, versioned and accessible only to the professional assigned to your case. We never share data with third parties without your consent."}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('624ced44-76af-4174-ab3e-9cdd7df01dd2', 'faqs', 'what-happens-after-i-submit-my-request', 'What happens after I submit my request?', 'PUBLISHED', 9, '{"question":"What happens after I submit my request?","answer":"You receive a confirmation immediately. Within one working day an expert calls to understand your requirement and shares a fixed-fee proposal and document checklist."}', 1, 'seed', NOW(6), NOW(6), NOW(6));

