INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('5af24027-c977-47d8-9c73-c0382984bccc', 'resources', 'compliance-calendar-fy-2026-27', 'Compliance calendar for FY 2026-27: every due date in one place', 'PUBLISHED', 0, '{"slug":"compliance-calendar-fy-2026-27","category":"tax-updates","date":"2026-04-01","title":"Compliance calendar for FY 2026-27: every due date in one place","excerpt":"Income tax, GST, TDS and ROC deadlines for the year, organised month by month so you can plan cash flow and paperwork.","readingTime":"6 min read","body":["Missing a statutory deadline is expensive: late fees, interest and in some cases loss of input credit or director disqualification. This calendar consolidates the recurring due dates every Indian business and taxpayer should track.","Monthly: GSTR-1 (11th), GSTR-3B (20th), TDS deposit (7th), PF and ESI (15th). Quarterly: TDS statements, advance tax instalments (15 June, 15 September, 15 December, 15 March). Annual: ITR (31 July for non-audit cases), tax audit (30 September), GSTR-9 (31 December), AOC-4 and MGT-7 (within 30 and 60 days of the AGM).","Dates can shift when the government issues extensions. Our clients receive reminders through the portal seven days before every applicable deadline."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('427c00d5-9d16-4d2c-b705-7e05ef89d51b', 'resources', 'old-vs-new-tax-regime-which-should-you-pick', 'Old vs. new tax regime: a practical way to decide', 'PUBLISHED', 1, '{"slug":"old-vs-new-tax-regime-which-should-you-pick","category":"income-tax-guides","date":"2026-03-18","title":"Old vs. new tax regime: a practical way to decide","excerpt":"The new regime is the default, but the old one still wins for many taxpayers with HRA and large deductions. Here is how to compare.","readingTime":"5 min read","body":["The new regime offers lower slab rates but removes most deductions and exemptions. The old regime keeps deductions such as 80C, 80D, HRA and home-loan interest but taxes income at higher rates.","A quick heuristic: add up the deductions and exemptions you can genuinely claim. If they exceed roughly ₹3.75–4 lakh on a ₹15 lakh salary, the old regime is usually better. Below that, the new regime typically wins.","Salaried taxpayers can switch every year; those with business income can switch out of the new regime only once. Run both computations before filing rather than assuming."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('fed4f617-ced8-468a-b86a-f22da36f3fe2', 'resources', 'gstr-2b-reconciliation-checklist', 'GSTR-2B reconciliation: a checklist to protect your input tax credit', 'PUBLISHED', 2, '{"slug":"gstr-2b-reconciliation-checklist","category":"gst-updates","date":"2026-02-27","title":"GSTR-2B reconciliation: a checklist to protect your input tax credit","excerpt":"Input credit is only as good as your vendors'' filings. A monthly reconciliation routine keeps your credit safe and your 3B accurate.","readingTime":"4 min read","body":["GSTR-2B is the auto-drafted statement of eligible input tax credit for a tax period. Credit not appearing in it is generally not available, regardless of what your purchase register says.","Each month, match purchase invoices to GSTR-2B by GSTIN, invoice number and taxable value. Classify differences as missing in portal, missing in books, mismatch, or duplicate, and follow up with vendors before filing GSTR-3B.","Keep a running list of vendors who consistently file late. Consider withholding the tax component of their payments until credit reflects."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('110dd3a7-5624-4663-ad2b-aee8a9804097', 'resources', 'private-limited-vs-llp-for-founders', 'Private Limited vs. LLP: choosing a structure for your startup', 'PUBLISHED', 3, '{"slug":"private-limited-vs-llp-for-founders","category":"startup-guides","date":"2026-02-10","title":"Private Limited vs. LLP: choosing a structure for your startup","excerpt":"Investors prefer companies; consultants often prefer LLPs. Compare compliance cost, taxation and fundraising flexibility before you decide.","readingTime":"7 min read","body":["A Private Limited company allows equity fundraising, ESOPs and is the structure most venture investors expect. It carries higher annual compliance: board meetings, statutory audit regardless of turnover, and detailed ROC filings.","An LLP is simpler and cheaper to maintain, taxed at a flat rate with no dividend distribution complications, but cannot issue ESOPs or raise equity in the conventional sense.","If you plan to raise institutional money within 18 months, incorporate a company. If you are a services partnership without external investors, an LLP is often the better fit."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('cd5c358a-7ac6-4e6b-943e-63ada6e57736', 'resources', 'roc-annual-filing-guide-for-small-companies', 'ROC annual filings for small companies: forms, timelines and penalties', 'PUBLISHED', 4, '{"slug":"roc-annual-filing-guide-for-small-companies","category":"business-compliance","date":"2026-01-22","title":"ROC annual filings for small companies: forms, timelines and penalties","excerpt":"AOC-4, MGT-7A, DIR-3 KYC and ADT-1 explained for directors who want to stay compliant without surprises.","readingTime":"5 min read","body":["Every company must hold an AGM within six months of the financial year end and file its financial statements (AOC-4) within 30 days and annual return (MGT-7 or MGT-7A for small companies) within 60 days of the AGM.","Directors must complete DIR-3 KYC annually by 30 September. Auditor appointments are reported in ADT-1.","Late filing attracts ₹100 per day per form with no ceiling. Repeated non-filing for two years can lead to strike-off and director disqualification for five years."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('416c4681-23f2-466d-9d74-c5796e6e854f', 'resources', 'advance-tax-for-freelancers-and-consultants', 'Advance tax for freelancers and consultants: how to avoid interest', 'PUBLISHED', 5, '{"slug":"advance-tax-for-freelancers-and-consultants","category":"financial-planning","date":"2026-01-08","title":"Advance tax for freelancers and consultants: how to avoid interest","excerpt":"If your tax liability exceeds ₹10,000 in a year, you must pay in instalments. Here is a simple system to stay ahead.","readingTime":"4 min read","body":["Advance tax is due in four instalments: 15% by 15 June, 45% by 15 September, 75% by 15 December and 100% by 15 March. Presumptive taxpayers under section 44ADA can pay the full amount by 15 March.","Estimate annual income conservatively each quarter, subtract TDS already deducted by clients, and pay the balance through Challan 280.","Shortfalls attract interest under sections 234B and 234C at 1% per month. Setting aside 20–25% of every receipt in a separate account makes this painless."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('a983382c-5827-4e78-a5a8-76f150576667', 'resources', 'budget-2026-key-changes-for-individual-taxpayers', 'Budget 2026: key changes individual taxpayers should know', 'PUBLISHED', 6, '{"slug":"budget-2026-key-changes-for-individual-taxpayers","category":"tax-updates","date":"2026-02-02","title":"Budget 2026: key changes individual taxpayers should know","excerpt":"A summary of the announcements that affect salaried employees, investors and senior citizens, and what to do before 31 March.","readingTime":"6 min read","body":["This note summarises the headline proposals relevant to individuals. Provisions take effect from the dates specified in the Finance Act once passed, so confirm applicability with your professional before acting.","Review your regime choice, revisit investment declarations with your employer, and check whether any capital gains transactions should be completed before or after the financial year end.","Our clients receive a personalised impact note through the portal after every Budget."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('43bd897e-8a6d-4df1-aa3d-17a665092c68', 'resources', 'e-invoicing-threshold-what-small-businesses-must-do', 'E-invoicing: what businesses crossing the threshold must do', 'PUBLISHED', 7, '{"slug":"e-invoicing-threshold-what-small-businesses-must-do","category":"gst-updates","date":"2025-12-15","title":"E-invoicing: what businesses crossing the threshold must do","excerpt":"Once your aggregate turnover crosses the notified limit, every B2B invoice needs an IRN. Here is the setup checklist.","readingTime":"4 min read","body":["E-invoicing applies to registered persons whose aggregate turnover in any preceding financial year from 2017-18 crossed the notified threshold. Applicability is permanent once triggered.","Register on the Invoice Registration Portal, integrate your billing software or use the offline utility, and ensure invoices carry the IRN and QR code before they are shared with customers.","Cancellation is allowed within 24 hours; after that, issue a credit note. Build this into your billing team''s process from day one."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));

-- videos (2)
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('1a29951b-f9c1-49f0-a862-5ffbba01144d', 'videos', 'itr', 'How to file your Income Tax Return (ITR) with TaxFilr', 'PUBLISHED', 0, '{"id":"itr","title":"How to file your Income Tax Return (ITR) with TaxFilr","description":"Upload Form 16, review the extracted salary and TDS, add other income and deductions, compare the Old and New regimes and generate your ITR JSON — then download it or hand it to an expert for filing.","duration":"2 min","file":"taxfilr-itr-walkthrough","startHref":"/filing/upload","startLabel":"Start my ITR","steps":["Log in or register from Get Started.","Open Filing → Upload Form 16 (drag & drop the PDF, or try the sample).","Review the extracted salary, TDS and employer details.","Add other income and deductions (80C, 80D, HRA…).","Compare tax under the Old and New regimes.","Check the tax-saving suggestions.","Enter your refund bank account and generate the ITR JSON.","Download the JSON or send it to a TaxFilr expert; track status on the summary page."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('381a0ade-1ef4-463f-8ef0-dbcf70252840', 'videos', 'gst', 'How to prepare and file a GST return with TaxFilr', 'PUBLISHED', 1, '{"id":"gst","title":"How to prepare and file a GST return with TaxFilr","description":"Register your GSTIN, start a GSTR-1 / GSTR-3B return for a period, record sales and purchase invoices, reconcile against GSTR-2B and send the return to a GST professional for filing.","duration":"2 min","file":"taxfilr-gst-walkthrough","startHref":"/gst","startLabel":"Open GST","steps":["Log in and open GST from the top menu.","Add your business under Registrations: GSTIN, legal name, state and signatory.","Go to GST returns, pick the registration, return type and period, then Create return.","Record sales and purchase invoices in the Invoice book, or upload a CSV.","Run Reconciliation to match your books against GSTR-2B and fix mismatches.","Click Send for review — a GST professional files it and the ARN appears on your return."]}', 1, 'seed', NOW(6), NOW(6), NOW(6));

-- legal (4)
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('3a8ae16f-9c83-4fd5-a8b7-7fbe80298c5f', 'legal', 'privacy', 'Privacy Policy', 'PUBLISHED', 0, '{"slug":"privacy","title":"Privacy Policy","updated":"1 April 2026","sections":[{"heading":"Information we collect","paragraphs":["When you request a callback, book a consultation or use the TaxFilr client portal, we collect the information you provide: your name, mobile number, email address, the type of client you are and the service you need.","When you become a client we additionally collect the identity, income, business and financial documents required to prepare your filings — for example PAN, Aadhaar, Form 16, bank statements, invoices and GST registration details."]},{"heading":"How we use it","paragraphs":["We use your information only to:"],"bullets":["Contact you about your enquiry and deliver the services you engage us for.","Prepare, review and file returns and forms with the relevant authorities on your instruction.","Send deadline reminders, filing status updates and service notifications.","Meet our legal, professional and record-keeping obligations."]},{"heading":"Sharing and disclosure","paragraphs":["We do not sell your personal information. We share it only with government portals when filing on your behalf, with regulated sub-processors (cloud hosting, communication tools) bound by confidentiality, and where required by law."]},{"heading":"Security","paragraphs":["Documents are stored encrypted at rest and in transit, access is limited to the professionals assigned to your engagement, and every access is logged. Staff accounts require multi-factor authentication."]},{"heading":"Retention and your rights","paragraphs":["We retain engagement records for the period required by applicable tax and professional regulations, after which they are securely deleted. You may request access to, correction of, or deletion of your personal information (subject to legal retention requirements) by contacting us."]}]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('eef9d192-e892-4b91-b24f-4a64adf66096', 'legal', 'terms', 'Terms of Service', 'PUBLISHED', 1, '{"slug":"terms","title":"Terms of Service","updated":"1 April 2026","sections":[{"heading":"Engagement","paragraphs":["These terms govern the professional services provided by TaxFilr Advisory Private Limited (\\"we\\", \\"us\\"). By requesting a service, paying a fee or using the client portal you agree to these terms.","Each engagement is scoped by the plan or proposal you accept. Work outside that scope is quoted separately before it begins."]},{"heading":"Fees and government charges","paragraphs":["Our professional fees are fixed and communicated in advance. Government fees, stamp duty, penalties, interest and taxes payable to any authority are separate, are your responsibility and are never included in our fees unless stated in writing."]},{"heading":"Your responsibilities","paragraphs":["Timely and accurate filing depends on you providing complete and correct information. You agree to:"],"bullets":["Share all documents and information reasonably requested, within the timelines communicated.","Review and approve computations, returns and drafts before we submit them.","Inform us promptly of notices, changes in business structure or other events affecting your compliance."]},{"heading":"Filing and acknowledgements","paragraphs":["Where we file on your behalf we do so using official government channels or, where electronic integration is unavailable, manually with your authorisation. We record acknowledgement numbers exactly as issued by the authority and never generate or represent an acknowledgement that has not been issued."]},{"heading":"Limitation of liability","paragraphs":["We exercise professional care and skill. Our aggregate liability for any engagement is limited to the professional fees paid for that engagement. We are not liable for penalties or interest arising from information provided late or inaccurately, or from decisions of any authority."]},{"heading":"Governing law","paragraphs":["These terms are governed by the laws of India and subject to the exclusive jurisdiction of the courts of Bengaluru."]}]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('2392ecf7-f1a0-4fd6-a679-bf28b7f250b7', 'legal', 'disclaimer', 'Disclaimer', 'PUBLISHED', 2, '{"slug":"disclaimer","title":"Disclaimer","updated":"1 April 2026","sections":[{"heading":"General information only","paragraphs":["Content on this website, including articles, calculators, guides and FAQs, is provided for general information and does not constitute professional, legal, tax or financial advice. Laws and rates change frequently and outcomes depend on individual facts."]},{"heading":"No government affiliation","paragraphs":["TaxFilr is an independent professional services firm. We are not affiliated with, endorsed by or acting on behalf of the Income Tax Department, the Goods and Services Tax Network, the Ministry of Corporate Affairs or any other government body."]},{"heading":"Illustrative figures","paragraphs":["Statistics, testimonials, savings examples and pricing displayed on this website are illustrative and may be updated at any time. Actual fees are confirmed in your engagement proposal."]}]}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('6b41c7ed-3ebf-4fe1-9345-0d52412ad9be', 'legal', 'refund', 'Refund & Cancellation Policy', 'PUBLISHED', 3, '{"slug":"refund","title":"Refund & Cancellation Policy","updated":"1 April 2026","sections":[{"heading":"Before work begins","paragraphs":["If you cancel before we have started work on your engagement, professional fees paid are refunded in full within 7–10 working days to the original payment method."]},{"heading":"After work begins","paragraphs":["Once our professionals have begun reviewing documents or preparing your filing, fees for work completed are non-refundable. Any unused portion of a multi-service package may be refunded at our discretion, less work already performed."]},{"heading":"Government fees","paragraphs":["Statutory fees, stamp duty and taxes paid to any authority on your behalf are non-refundable once remitted."]},{"heading":"How to request a refund","paragraphs":["Email support@taxfilr.in with your registered mobile number and engagement reference. We respond to every request within 3 working days."]}]}', 1, 'seed', NOW(6), NOW(6), NOW(6));

-- field_guides (42)
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('7e8c5d11-cfc2-4dab-90b0-3083d9302690', 'field_guides', 'itr-business-turnover', 'Total sales in the year (business)', 'PUBLISHED', 0, '{"key":"itr.business.turnover","label":"Total sales in the year (business)","hint":"Everything your shop or business sold from 1 April to 31 March, before any expenses.","whereToFind":"Your sales register, GST returns (GSTR-1 / GSTR-3B totals) or bank statement credits.","example":"If you sold goods worth ₹32,50,000 in the year, type 3250000.","hindi":"साल भर की कुल बिक्री (खर्चा घटाने से पहले)। GST रिटर्न या बिक्री रजिस्टर से लें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('feb602e6-c7b3-43e5-9396-a38453d351d1', 'field_guides', 'itr-business-profit', 'Profit from business', 'PUBLISHED', 1, '{"key":"itr.business.profit","label":"Profit from business","hint":"Sales minus your business expenses (purchases, rent, salaries, electricity). If you use the simple ''presumptive'' scheme, at least 6% of digital sales / 8% of cash sales.","whereToFind":"Profit & loss statement from your accountant, or estimate: total sales − total expenses.","example":"Sales ₹32,50,000 with expenses ₹28,00,000 → profit ₹4,50,000 → type 450000.","hindi":"बिक्री में से खर्चा घटाने के बाद जो बचा, वह मुनाफ़ा। छोटे व्यापारी 6%/8% वाला आसान (presumptive) तरीका भी चुन सकते हैं।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('ef9576c7-cfde-4df5-afc2-4bfc0e55356a', 'field_guides', 'itr-profession-receipts', 'Fees received (doctor, lawyer, freelancer, consultant)', 'PUBLISHED', 2, '{"key":"itr.profession.receipts","label":"Fees received (doctor, lawyer, freelancer, consultant)","hint":"Total fees you received for professional work in the year. Leave 0 if you only run a shop / trading business.","whereToFind":"Invoices you raised, or Form 26AS / AIS on the income-tax portal (payments where TDS was cut).","example":"A freelance designer paid ₹9,00,000 in the year types 900000.","hindi":"पेशेवर काम (डॉक्टर, वकील, फ्रीलांस) की कुल फ़ीस। दुकान/व्यापार वाले 0 छोड़ें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('a7adc74b-ed2f-4bd2-93fd-314ea74c8fa9', 'field_guides', 'itr-profession-profit', 'Profit from profession', 'PUBLISHED', 3, '{"key":"itr.profession.profit","label":"Profit from profession","hint":"Fees minus your work expenses. Under the simple scheme (Section 44ADA) you can declare 50% of fees as profit and skip bookkeeping.","example":"Fees ₹9,00,000 → simple scheme profit ₹4,50,000 → type 450000.","hindi":"फ़ीस में से खर्चा घटाकर मुनाफ़ा। आसान तरीके में फ़ीस का 50% मुनाफ़ा मान सकते हैं।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('ab1b9925-d58e-45bd-a97d-b3dc97fe6b84', 'field_guides', 'itr-tax-advancetax', 'Tax you already paid yourself (advance / self-assessment tax)', 'PUBLISHED', 4, '{"key":"itr.tax.advanceTax","label":"Tax you already paid yourself (advance / self-assessment tax)","hint":"Any income tax you paid directly through a bank challan during the year. Leave 0 if you never paid tax yourself.","whereToFind":"Form 26AS on incometax.gov.in → ''Part C – Taxes paid'', or the challan receipt (Challan 280) from your bank.","example":"Paid ₹40,000 in December and ₹35,000 in March → type 75000.","hindi":"जो टैक्स आपने खुद बैंक चालान से जमा किया (एडवांस टैक्स)। Form 26AS में दिखता है।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('6436f6b4-ea16-4d36-85a5-b5623158e3c0', 'field_guides', 'itr-tax-tdsother', 'TDS cut by customers or banks', 'PUBLISHED', 5, '{"key":"itr.tax.tdsOther","label":"TDS cut by customers or banks","hint":"Tax that others deducted before paying you (customers deducting 1–2% on your bills, banks on FD interest). This is already paid on your behalf and reduces what you owe.","whereToFind":"Form 26AS / AIS on incometax.gov.in, or Form 16A certificates given by the payer.","example":"Form 26AS shows TDS of ₹18,500 → type 18500.","hindi":"ग्राहकों या बैंक ने भुगतान से पहले जो टैक्स काटा (TDS)। Form 26AS में देखें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('88b34449-25c8-4adb-ac7f-fd03cd5775a8', 'field_guides', 'itr-interest-savings', 'Interest from savings bank account', 'PUBLISHED', 6, '{"key":"itr.interest.savings","label":"Interest from savings bank account","hint":"Interest the bank added to your savings account in the year (all banks together).","whereToFind":"Bank passbook / statement — look for lines called ''Int.Pd'' or ''Interest credit'', usually every 3 months. Or your AIS on the income-tax portal.","example":"₹1,240 + ₹1,310 + ₹1,190 + ₹1,400 across the year → type 5140.","hindi":"बचत खाते पर बैंक ने जो ब्याज दिया (सारे बैंक जोड़कर)। पासबुक में ''Int'' लाइन देखें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('298476a0-9725-45b2-8ccb-1963273cd92f', 'field_guides', 'itr-interest-fd', 'Interest from fixed deposits (FD)', 'PUBLISHED', 7, '{"key":"itr.interest.fd","label":"Interest from fixed deposits (FD)","hint":"Interest earned on FDs this year, even if the FD has not matured yet.","whereToFind":"Bank''s ''Interest certificate'' (downloadable from net banking) or Form 26AS / AIS.","example":"FD of ₹5,00,000 at 7% → about ₹35,000 → type 35000.","hindi":"FD पर मिला ब्याज (चाहे FD अभी पूरी न हुई हो)। बैंक का interest certificate देखें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('df2386e0-f190-4d53-be9c-b217174dd43a', 'field_guides', 'itr-interest-rd', 'Interest from recurring deposits (RD) or post office', 'PUBLISHED', 8, '{"key":"itr.interest.rd","label":"Interest from recurring deposits (RD) or post office","hint":"Interest on RDs, post-office schemes (NSC, KVP, MIS). Leave 0 if none.","whereToFind":"RD passbook or post-office statement.","hindi":"RD या पोस्ट ऑफिस योजनाओं का ब्याज। न हो तो 0 छोड़ें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('c1ad5e2f-5995-464a-a6fa-359d1b3588c2', 'field_guides', 'itr-gains-short', 'Profit on shares / mutual funds sold within 1 year', 'PUBLISHED', 9, '{"key":"itr.gains.short","label":"Profit on shares / mutual funds sold within 1 year","hint":"Money you gained by selling shares, mutual funds or property you held for a short time. Only the profit, not the sale amount.","whereToFind":"''Capital gains statement'' from your broker (Zerodha, Groww, etc.) or mutual fund house (CAMS / KFintech).","example":"Bought shares for ₹1,00,000, sold for ₹1,20,000 after 6 months → gain ₹20,000 → type 20000.","hindi":"1 साल के अंदर बेचे गए शेयर/म्यूचुअल फंड पर हुआ मुनाफ़ा (सिर्फ़ मुनाफ़ा, बिक्री रकम नहीं)।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('68f97365-ddab-448b-9336-5c0dddf1a8d6', 'field_guides', 'itr-gains-long', 'Profit on shares / mutual funds / property held over 1 year', 'PUBLISHED', 10, '{"key":"itr.gains.long","label":"Profit on shares / mutual funds / property held over 1 year","hint":"Profit from selling things you held for more than a year (2 years for property). Gains up to ₹1.25 lakh on shares are tax-free.","whereToFind":"Same capital gains statement from the broker / fund house; for property, the sale deed and purchase deed.","hindi":"1 साल से ज़्यादा रखे शेयर/फंड या 2 साल से ज़्यादा रखी प्रॉपर्टी बेचने पर मुनाफ़ा।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('c831a782-e58b-4086-b2f1-a3226f23f570', 'field_guides', 'itr-other-rent', 'Rent you received (whole year)', 'PUBLISHED', 11, '{"key":"itr.other.rent","label":"Rent you received (whole year)","hint":"Total rent from a house or shop you own and let out. Type the yearly amount, not monthly.","whereToFind":"Rent agreement or bank credits from the tenant.","example":"₹15,000 a month → type 180000.","hindi":"अपनी दुकान/मकान किराये पर देकर साल भर में मिला कुल किराया (मासिक नहीं, सालाना)।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('30405597-fa6b-4bba-9fb2-489b99dbad8c', 'field_guides', 'itr-other-misc', 'Any other income', 'PUBLISHED', 12, '{"key":"itr.other.misc","label":"Any other income","hint":"Anything else: commission, lottery, cash gifts over ₹50,000 from non-relatives, family pension, dividend from shares.","whereToFind":"Your bank statement; dividends appear in AIS on the income-tax portal.","hindi":"बाकी कोई आय: कमीशन, डिविडेंड, ₹50,000 से ऊपर के गिफ्ट, लॉटरी आदि।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('661da6e4-67e2-4aa2-bba9-a6862cce4b85', 'field_guides', 'itr-hra-rentpaid', 'Rent you paid for your home (whole year)', 'PUBLISHED', 13, '{"key":"itr.hra.rentPaid","label":"Rent you paid for your home (whole year)","hint":"Only if you live in a rented house AND your salary includes HRA. Business owners without salary can leave 0.","whereToFind":"Rent receipts or bank transfers to your landlord. Landlord PAN is needed if rent is over ₹1,00,000 a year.","example":"₹12,000 a month → type 144000.","hindi":"अगर आप किराये के घर में रहते हैं और सैलरी में HRA मिलता है, तो साल भर का दिया किराया।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('843add1c-4229-42b2-81bb-98a2bd402c04', 'field_guides', 'itr-ded-80c', 'Savings that reduce tax — LIC, PPF, ELSS, child school fees, home-loan principal (80C)', 'PUBLISHED', 14, '{"key":"itr.ded.80c","label":"Savings that reduce tax — LIC, PPF, ELSS, child school fees, home-loan principal (80C)","hint":"Add up what you paid this year into these: life-insurance premium, PPF, ELSS mutual funds, tax-saver FD, NSC, children''s tuition fees, home-loan principal. Maximum benefit ₹1,50,000.","whereToFind":"Premium receipts, PPF passbook, school fee receipts, home-loan statement (''principal repaid'').","example":"LIC ₹36,000 + PPF ₹50,000 + school fees ₹40,000 → type 126000.","hindi":"LIC, PPF, ELSS, बच्चों की स्कूल फ़ीस, होम लोन का मूल (principal) — सब जोड़कर। अधिकतम ₹1.5 लाख का फ़ायदा।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('ad327257-19b6-408f-8ddb-956c0e2b0daa', 'field_guides', 'itr-ded-nps', 'Money put into NPS pension account (80CCD(1B))', 'PUBLISHED', 15, '{"key":"itr.ded.nps","label":"Money put into NPS pension account (80CCD(1B))","hint":"Your own NPS deposits this year. Extra ₹50,000 benefit over and above 80C. Leave 0 if you don''t have NPS.","whereToFind":"NPS statement from the NSDL / Protean CRA app or SMS.","hindi":"NPS पेंशन खाते में डाला पैसा। 80C के ऊपर ₹50,000 तक अलग से फ़ायदा।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('82bbc79a-4ded-47c1-ab0d-be0f6b529aea', 'field_guides', 'itr-ded-80d', 'Health insurance premium (mediclaim) for family and parents (80D)', 'PUBLISHED', 16, '{"key":"itr.ded.80d","label":"Health insurance premium (mediclaim) for family and parents (80D)","hint":"Premium paid for health insurance of you, spouse, children and parents. Up to ₹25,000 for family, plus ₹50,000 for senior-citizen parents.","whereToFind":"Policy premium receipt or the ''80D certificate'' from your insurer''s app.","example":"Family policy ₹18,000 + parents'' policy ₹32,000 → type 50000.","hindi":"अपने परिवार और माता-पिता के हेल्थ इंश्योरेंस (मेडिक्लेम) का प्रीमियम।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('fb44939c-29cd-4d88-ae4c-a3f9f5d86ffa', 'field_guides', 'itr-ded-80tta', 'Savings-account interest benefit (80TTA)', 'PUBLISHED', 17, '{"key":"itr.ded.80tta","label":"Savings-account interest benefit (80TTA)","hint":"Type the same savings-account interest you entered above, up to ₹10,000 — that much is tax-free. Senior citizens get ₹50,000 (80TTB).","hindi":"ऊपर लिखा बचत खाते का ब्याज यहाँ दोबारा लिखें (₹10,000 तक टैक्स-फ्री)।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('38462b7b-6de7-4e13-a335-5954b5bd350c', 'field_guides', 'itr-ded-homeloaninterest', 'Interest paid on home loan (Section 24)', 'PUBLISHED', 18, '{"key":"itr.ded.homeLoanInterest","label":"Interest paid on home loan (Section 24)","hint":"Only the interest part of your home-loan EMIs this year (not the principal). Maximum ₹2,00,000 for a self-occupied house.","whereToFind":"''Provisional interest certificate'' from your bank''s net banking / app.","example":"Certificate shows interest ₹1,86,000 → type 186000.","hindi":"होम लोन की EMI में ब्याज (interest) वाला हिस्सा। बैंक का interest certificate देखें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('348b825c-7786-4549-a19e-c6984a93e106', 'field_guides', 'itr-ded-other', 'Other deductions (donations, education-loan interest, disability)', 'PUBLISHED', 19, '{"key":"itr.ded.other","label":"Other deductions (donations, education-loan interest, disability)","hint":"Donations to approved charities (80G), interest on an education loan (80E), disability (80U). Leave 0 if none.","whereToFind":"Donation receipt with the charity''s 80G registration number; education-loan interest certificate.","hindi":"दान (80G), एजुकेशन लोन का ब्याज (80E), दिव्यांगता (80U) आदि।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('2ae145ba-20cc-46da-bc81-2e13b9064d6b', 'field_guides', 'gst-profile-gstin', 'Your GST number (GSTIN)', 'PUBLISHED', 20, '{"key":"gst.profile.gstin","label":"Your GST number (GSTIN)","hint":"The 15-character number on your GST registration certificate. It starts with your state code (e.g. 27 for Maharashtra) and contains your PAN.","whereToFind":"GST registration certificate (Form REG-06), or on any invoice you have issued. Also on gst.gov.in after login.","example":"27ABCDE1234F1Z5","hindi":"आपका 15 अंकों का GST नंबर, GST सर्टिफिकेट या अपने बिल पर लिखा होता है।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('9bc45512-0483-43b5-ae99-304b5c9107bb', 'field_guides', 'gst-profile-legalname', 'Legal name (as on PAN)', 'PUBLISHED', 21, '{"key":"gst.profile.legalName","label":"Legal name (as on PAN)","hint":"The name printed on your PAN card / GST certificate — for a proprietor this is your own name.","whereToFind":"GST certificate, ''Legal Name of Business'' line.","example":"Ramesh Kumar Gupta","hindi":"PAN कार्ड / GST सर्टिफिकेट पर लिखा नाम। प्रोप्राइटर के लिए आपका अपना नाम।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('8cb370a2-651c-4eb1-a6c5-2e3a25628e29', 'field_guides', 'gst-profile-tradename', 'Shop / brand name (trade name)', 'PUBLISHED', 22, '{"key":"gst.profile.tradeName","label":"Shop / brand name (trade name)","hint":"The name on your shop board or bills, if different from the legal name.","example":"Gupta General Store","hindi":"दुकान के बोर्ड या बिल पर लिखा नाम, अगर कानूनी नाम से अलग है।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('6971b865-2811-43f2-8287-f47890ea6181', 'field_guides', 'gst-profile-businesstype', 'Type of business', 'PUBLISHED', 23, '{"key":"gst.profile.businessType","label":"Type of business","hint":"Proprietorship (single owner), Partnership, LLP, Private Limited, HUF, etc.","whereToFind":"GST certificate, ''Constitution of Business'' line.","example":"Proprietorship","hindi":"व्यवसाय का प्रकार: प्रोप्राइटरशिप, पार्टनरशिप, प्राइवेट लिमिटेड आदि।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('c6a627a8-bee4-4589-9ba0-3965edf601dd', 'field_guides', 'gst-profile-state', 'State of registration', 'PUBLISHED', 24, '{"key":"gst.profile.state","label":"State of registration","hint":"The state where your business is registered — decides whether a sale is ''within state'' (CGST + SGST) or ''to another state'' (IGST).","example":"Maharashtra","hindi":"जिस राज्य में GST रजिस्ट्रेशन है।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('af423bb7-93df-469e-bf7e-c16b46dd8a0c', 'field_guides', 'gst-profile-address', 'Registered business address', 'PUBLISHED', 25, '{"key":"gst.profile.address","label":"Registered business address","hint":"Address printed on the GST certificate (''Principal Place of Business'').","hindi":"GST सर्टिफिकेट पर लिखा मुख्य कारोबार का पता।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('3808592c-bcd3-41f7-8bf0-a13e59151b9e', 'field_guides', 'gst-profile-signatory', 'Person who signs the return', 'PUBLISHED', 26, '{"key":"gst.profile.signatory","label":"Person who signs the return","hint":"The owner or partner responsible for filing — usually you.","example":"Ramesh Kumar Gupta","hindi":"रिटर्न पर हस्ताक्षर करने वाला व्यक्ति — आम तौर पर मालिक।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('7cd68b66-b1aa-4c7f-9dda-a2463e5e77d0', 'field_guides', 'gst-profile-designation', 'Their role', 'PUBLISHED', 27, '{"key":"gst.profile.designation","label":"Their role","hint":"Proprietor, Partner, Director, Manager…","example":"Proprietor","hindi":"उनका पद: प्रोप्राइटर, पार्टनर, डायरेक्टर…"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('21219c2e-4539-4fb7-b329-21571898a668', 'field_guides', 'gst-return-type', 'Which return?', 'PUBLISHED', 28, '{"key":"gst.return.type","label":"Which return?","hint":"GSTR-1 = list of your sales (monthly/quarterly). GSTR-3B = summary where you pay the tax. GSTR-4 = yearly return for composition-scheme shops. GSTR-9 = yearly summary.","whereToFind":"Most regular shops file GSTR-1 and GSTR-3B every month; if you opted for the composition scheme, file GSTR-4.","hindi":"GSTR-1 = बिक्री की सूची, GSTR-3B = टैक्स भरने वाला सारांश, GSTR-4 = कंपोज़िशन स्कीम का सालाना रिटर्न।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('81ed669e-d2ea-4631-b303-9459be1054f1', 'field_guides', 'gst-return-period', 'Month the return is for', 'PUBLISHED', 29, '{"key":"gst.return.period","label":"Month the return is for","hint":"Pick the month whose sales/purchases you are reporting — not the month you are filing in.","example":"Filing in May for April''s sales → pick April.","hindi":"जिस महीने की बिक्री/खरीद बता रहे हैं वह महीना चुनें (फाइल करने का महीना नहीं)।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('a9b8ffe6-59cb-4b00-99e6-4a588ba9bb0e', 'field_guides', 'gst-invoice-documenttype', 'What is this document?', 'PUBLISHED', 30, '{"key":"gst.invoice.documentType","label":"What is this document?","hint":"Sales = bill you gave a customer. Purchase = bill a supplier gave you. Credit note = you reduced a customer''s bill / took goods back. Debit note = you charged extra.","hindi":"Sales = आपने ग्राहक को दिया बिल। Purchase = सप्लायर से मिला बिल। Credit note = बिल घटाया/सामान वापस लिया।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('dca4ea12-9c7b-4261-8bff-ee85448473bb', 'field_guides', 'gst-invoice-supplytype', 'Does GST apply to it?', 'PUBLISHED', 31, '{"key":"gst.invoice.supplyType","label":"Does GST apply to it?","hint":"Taxable = normal GST bill. Exempt / Nil-rated = items with no GST (fresh vegetables, milk, books). Zero-rated = exports. Reverse charge = the buyer pays the GST (e.g. transporter, lawyer bills).","hindi":"Taxable = सामान्य GST बिल। Exempt/Nil = जिन पर GST नहीं (सब्ज़ी, दूध)। Zero-rated = एक्सपोर्ट।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('44d4f422-aefc-4c9e-8dd9-106b72d49f30', 'field_guides', 'gst-invoice-number', 'Bill number', 'PUBLISHED', 32, '{"key":"gst.invoice.number","label":"Bill number","hint":"The invoice number printed on the bill. Sales bills must be in a running series for the year.","example":"INV/2024-25/0147","hindi":"बिल पर छपा इनवॉइस नंबर।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('9c04a734-1a60-4a6b-abea-8a6f3958f03a', 'field_guides', 'gst-invoice-date', 'Bill date', 'PUBLISHED', 33, '{"key":"gst.invoice.date","label":"Bill date","hint":"Date printed on the bill.","hindi":"बिल की तारीख।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('7b6e82a7-693b-4e38-8428-b7c6ca24f8c2', 'field_guides', 'gst-invoice-counterpartygstin', 'Customer''s / supplier''s GST number', 'PUBLISHED', 34, '{"key":"gst.invoice.counterpartyGstin","label":"Customer''s / supplier''s GST number","hint":"The other party''s GSTIN, if they are GST-registered (B2B). Leave blank for walk-in customers without GST (B2C).","whereToFind":"Printed on their bill or letterhead; verify on gst.gov.in → ''Search Taxpayer''.","example":"07AAACX9999Q1Z3","hindi":"दूसरी पार्टी का GST नंबर (अगर है)। बिना GST वाले ग्राहक के लिए खाली छोड़ें।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('eacd7591-f1bc-4dde-bae5-cb0552c848de', 'field_guides', 'gst-invoice-counterpartyname', 'Customer''s / supplier''s name', 'PUBLISHED', 35, '{"key":"gst.invoice.counterpartyName","label":"Customer''s / supplier''s name","hint":"Name on their bill. For walk-in cash sales you can write ''Cash sale''.","example":"Sharma Traders","hindi":"ग्राहक/सप्लायर का नाम। नकद बिक्री के लिए ''Cash sale'' लिख सकते हैं।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('5f5f1496-b836-44f4-a51b-2fd70cc6d446', 'field_guides', 'gst-invoice-placeofsupply', 'Where the goods were delivered (state)', 'PUBLISHED', 36, '{"key":"gst.invoice.placeOfSupply","label":"Where the goods were delivered (state)","hint":"The state where the buyer received the goods or service. Same state as yours → CGST + SGST. Another state → IGST.","example":"Maharashtra","hindi":"जिस राज्य में सामान/सेवा पहुँची। अपना राज्य → CGST+SGST; दूसरा राज्य → IGST।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('10625723-c614-47d3-89c0-4989580be8a5', 'field_guides', 'gst-invoice-hsn', 'HSN / SAC code of the item', 'PUBLISHED', 37, '{"key":"gst.invoice.hsn","label":"HSN / SAC code of the item","hint":"The government''s item code: HSN for goods, SAC for services. Businesses under ₹5 crore need 4 digits; above that 6 digits.","whereToFind":"On your supplier''s bill, in your billing software, or search ''HSN code <item>'' on cbic-gst.gov.in.","example":"Rice = 1006, Mobile phones = 8517, Accounting services = 9982.","hindi":"सामान का सरकारी कोड (HSN) या सेवा का कोड (SAC)। सप्लायर के बिल पर मिल जाता है।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('d115b4a8-21e0-4793-acf4-7bc196242fa9', 'field_guides', 'gst-invoice-taxablevalue', 'Bill amount before GST', 'PUBLISHED', 38, '{"key":"gst.invoice.taxableValue","label":"Bill amount before GST","hint":"Value of the goods/services only, without adding GST.","example":"Item ₹10,000 + 18% GST ₹1,800 = bill ₹11,800 → type 10000.","hindi":"GST जोड़ने से पहले की रकम।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('b1f569d6-5ac9-43af-b5da-3da06f1cf0f4', 'field_guides', 'gst-invoice-cgst', 'CGST (central GST) on the bill', 'PUBLISHED', 39, '{"key":"gst.invoice.cgst","label":"CGST (central GST) on the bill","hint":"For sales within your own state, GST is split into two equal halves — this is the central half.","example":"18% GST on ₹10,000 → CGST ₹900.","hindi":"अपने राज्य में बिक्री पर GST का आधा हिस्सा (केंद्र)।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('ad44455a-3cf2-4804-945a-c0ea359cd274', 'field_guides', 'gst-invoice-sgst', 'SGST (state GST) on the bill', 'PUBLISHED', 40, '{"key":"gst.invoice.sgst","label":"SGST (state GST) on the bill","hint":"The state''s half — always equal to CGST for within-state sales.","example":"18% GST on ₹10,000 → SGST ₹900.","hindi":"अपने राज्य में बिक्री पर GST का आधा हिस्सा (राज्य)। CGST के बराबर।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));
INSERT IGNORE INTO cms_entries (id, collection, slug, title, status, sort_order, data, version, updated_by, created_at, updated_at, published_at)
VALUES ('7856232e-0a61-421a-8958-dfbaeba01269', 'field_guides', 'gst-invoice-igst', 'IGST (for sales to another state)', 'PUBLISHED', 41, '{"key":"gst.invoice.igst","label":"IGST (for sales to another state)","hint":"Used instead of CGST + SGST when the buyer is in a different state. Leave 0 for within-state bills.","example":"18% GST on ₹10,000 sold to Delhi from Mumbai → IGST ₹1,800.","hindi":"दूसरे राज्य में बिक्री पर पूरा GST यहाँ। अपने राज्य के बिल के लिए 0।"}', 1, 'seed', NOW(6), NOW(6), NOW(6));

